        if (Algebra::hasMethod(i, "Add")) {
            Algebra::addMethod(std::addressof(Algebra::Add))( &references[i], amounts[i] );
        }
    }
}

// Helper function to check if a member function exists
template<typename T, std::size_t N>
auto hasMethod(T& obj, std::size_t methodIndex) -> decltype(declval<T>().methodIndex(0))
{
    using methodType = decltype(declval<T>().methodIndex(0));
    return &obj->methodIndex;
}

// Helper function to call a member function
template<typename T, std::size_t N>
void addMethod(T& obj, std::size_t methodIndex, auto method) {
    using methodType = decltype(declval<T>().methodIndex(0));
    (obj->methodIndex)(method);
}

