       var xAcceleration: Double
       var yAcceleration: Double
       var zAcceleration: Double
   }
   ```

6. **Fetch and Update Accelerometer Data:**
   Create a `ContentView` that fetches accelerometer data and applies a 3D effect.

   ```swift
   class AccelerometerDataProxy: ObservableObject {
       private var accelerometer: CMMotionManager!
       private var motionUpdater: AnyCancellable!
       private let queue = DispatchQueue.main

       init() {
           let motionManager = CMMotionManager()
           accelerometer = motionManager

           // Start motion updates to get continuous data
           if motionManager.isAccelerometerAvailable {
               motionManager.accelerometerUpdateInterval = 0.1
               motionManager.startAccelerometerUpdates(to: queue) { newData, error in
                   guard let data = newData, let x = data.acceleration.x , let y = data.acceleration.y , let z = data.acceleration.z else { return }

                   let accelData = AccelerometerData(xAcceleration: x, yAcceleration: y, zAcceleration: z)

                   // Update your ObservableObject here
               }
           }

           // Fetch initial data after setup
           if motionManager.isAccelerometerAvailable {
               motionManager.startAccelerometerUpdates(to: queue) { newData, error in
                   guard let data = newData, let x = data.acceleration.x , let y = data.acceleration.y , let z = data.acceleration.z else { return }

                   let accelData = AccelerometerData(xAcceleration: x, yAcceleration: y, zAcceleration: z)

                   // Update your ObservableObject here
               }
           }
       }
       // Other ObservableObject properties and methods...
   }
   ```

7. **Use the Accelerometer Data in Your SwiftUI View:**

   Modify the `ContentView` to incorporate the accelerometer data and apply 3D transformations.

   ```swift
   struct ContentView: View {
       @ObservedObject var viewModel = AccelerometerDataProxy()
       var body: some View {
           GeometryReader { geometry in
               HStack {
                   let card = LineImage(voxelDim: CGFloat(10), acceleration: viewModel.xAcceleration, yAcceleration: viewModel.yAcceleration, zAcceleration: viewModel.zAcceleration)
