       var acceleration: Double
       var yAcceleration: Double
       var zAcceleration: Double

       var body: some View {
           Image("card")
               .frame(
                   width: voxelDim,
                   height: voxelDim,
               )
               .rotated
               .position(x: (voxelDim / 2), y: (voxelDim / 2))
