import java.util.Scanner;
class MyFraction
{
	int n1, d1;
	
	public MyFraction(int num1, int den1)
	{
		n1 = num1;
		d1 = den1;
	}
	
	public String toString() 
	{
		return Integer.toString(n1) + "/" + Integer.toString(d1);
		
	}
	
	public MyFraction multiply(MyFraction frac2)
	{
		int num2 = frac2.n1;
		int den2 = frac2.d1;
		
		return new MyFraction(n1 * num2, d1 * den2);
	}
	
	public MyFraction divide(MyFraction frac2)
	{
		int num2 = frac2.n1;
		int den2 = frac2.d1;
		
		return new MyFraction(n1 * den2, d1 * num2);
	}
	
	public MyFraction add(MyFraction frac2)
	{
		int num2 = frac2.n1;
		int den2 = frac2.d1;
		
		return new MyFraction(n1 * den2 + d1 * num2, d1 * den2);
		
	}

	public MyFraction sub(MyFraction frac2)
	{
		int num2 = frac2.n1;
		int den2 = frac2.d1;

		return new MyFraction(n1 * den2 - d1 * num2, d1 * den2);
		
	}
}
public class calculation
{
	public static void main(String[] args)
	{
		Scanner sc = new Scanner(System.in);
		System.out.println("Enter numerator and denominator for the first number.");
		int n1 = sc.nextInt();
		int d1 = sc.nextInt();
		System.out.println("Enter numerator and denominator for the 2nd number.");
