		MyFraction frac2 = new MyFraction(num2, den2);
		System.out.println("1. Add 2. Subtract 3. Multiplicate 4. Divide");
		int selOp = sc.nextInt();
		switch (selOp)
		{
			case 1:
				System.out.println(frac1.add(frac2));
				break;
			case 2:
				System.out.println(frac1.sub(frac2));
				break;
			case 3:
				System.out.println(frac1.multiply(frac2));
				break;
			case 4:
				System.out.println(frac1.divide(frac2));
				break;
			default:
				break;
		}
		
		
	}

}

